<script>
document.addEventListener('DOMContentLoaded', () => {

    const MIN_STAT = 1;
    const MAX_STAT = 20;
    const ancestryData = { '人类': {}, '精灵': {}, '兽人': {}, '矮人': {} };
    const attributeNames = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];

    const randomOriginTable = [ '埃拉诺亚王国的农夫之子', '圣辉城的街头孤儿', '皇家魔导学院元素学部的低年级生', '冥炎骑士团的见习侍从', '呼啸山脉的年轻矿工', '石锤派矮人铁匠的学徒', '往来于人类与矮人城邦间的商队护卫', '幸运之森的年轻巡林客', '支持新叶派的精灵竖琴手', '血牙荒原苍狼氏族的青年猎手', '兽人部落的萨满学徒', '潮汐之牙港口的渔夫', '埃拉诺亚边境村庄的猎户', '从小在魔导工坊长大的孤儿', '齿轮派矮人工程师的助手', '永恒春天城的一名花匠', '曾被亡灵海盗掳走后逃脱的水手', '家族破产，被迫在首都谋生的前小贵族', '对血神信仰感到怀疑的年轻兽人', '给贵族绘制纹章补贴家用的历史系学生' ];

    const randomTalentTable = [
        '魔力吞噬 (传奇)', '破魔之眼 (传奇)', '天赋掠夺 (传奇)','时空锚点 (传奇)', '法术融合 (稀有)', '快速吟唱 (稀有)', '多重施法 (稀有)', '完美复写 (稀有)', '魔力解析 (稀有)', '情绪共鸣 (普通)', '草木低语 (普通)', '元素亲和 (普通)', '过目成诵 (普通)', '炼金直觉 (普通)', '野性友和 (普通)', '魔导亲和 (普通)', '快速记忆 (普通)', '巧言灵舌 (普通)', '寻物预感 (普通)', '稳定之手 (普通)', '夜之视野 (普通)'
    ];

    let characterProfile = {};
    let appState = {
        difficulty: 'normal', totalStatPoints: 60, remainingStatPoints: 60,
        attributeMode: 'random', isAnimationSkipped: false,
        currentRollResult: null,
        activeAnimation: null, animationPromiseResolve: null 
    };

    const DOM = {
        difficultySelector: document.getElementById('difficulty-selector'),
        genesisFolio: document.getElementById('genesis-folio'),
        difficultyOptions: document.querySelectorAll('.difficulty-options button'),
        nameInput: document.getElementById('char-name'),
        genderRadios: document.querySelectorAll('input[name="gender"]'),
        raceSelect: document.getElementById('char-race'),
        attrModeToggle: document.getElementById('attr-mode-toggle'),
        manualStatsPanel: document.getElementById('manual-stats-panel'),
        randomStatsPanel: document.getElementById('random-stats-panel'),
        pointsPoolDisplay: document.querySelector('#points-pool-display strong'),
        manualAttributesGrid: document.getElementById('manual-attributes-grid'),
        randomAttributesGrid: document.getElementById('random-attributes-grid'),
        rollStatsBtn: document.getElementById('roll-stats-btn'),
        rollOriginBtn: document.getElementById('roll-origin-btn'),
        rollTalentBtn: document.getElementById('roll-talent-btn'),
        originInput: document.getElementById('origin-input'),
        talentInput: document.getElementById('talent-input'),
        customSettingsInput: document.getElementById('custom-settings-input'),
        finalSummary: document.getElementById('final-summary'),
        finalizeBtn: document.getElementById('finalize-btn'),
        rollingChamber: document.getElementById('rolling-chamber'),
        d20Visual: document.getElementById('d20-visual'),
        rollResultText: document.getElementById('roll-result-text'),
        skipRollBtn: document.getElementById('skip-roll-btn'),
    };

    function initializeCharacterProfile() {
        characterProfile = { name: '', gender: '男性', race: '人类', origin: '', talent: '', customSettings: '', attributes: {}, };
        const basePoints = Math.floor(appState.totalStatPoints / attributeNames.length);
        const remainder = appState.totalStatPoints % attributeNames.length;
        attributeNames.forEach((attr, index) => {
            characterProfile.attributes[attr] = basePoints + (index < remainder ? 1 : 0);
        });
        appState.remainingStatPoints = 0;
    }

    function syncView() {
        DOM.pointsPoolDisplay.textContent = appState.remainingStatPoints;
        attributeNames.forEach(attr => {
            const val = characterProfile.attributes[attr];
            const input = document.getElementById(`manual-attr-input-${attr}`);
            const btnPlus = document.getElementById(`manual-attr-plus-${attr}`);
            const btnMinus = document.getElementById(`manual-attr-minus-${attr}`);
            if (input) input.value = val;
            if (btnPlus) btnPlus.disabled = val >= MAX_STAT || appState.remainingStatPoints <= 0;
            if (btnMinus) btnMinus.disabled = val <= MIN_STAT;
            const randomEl = document.getElementById(`random-attr-val-${attr}`);
            if (randomEl) randomEl.textContent = val || '0';
        });

        const { name, gender, race, attributes, origin, talent, customSettings } = characterProfile;
        let summary = `角色档案\n==================\n`;
        summary += `名讳: ${name || '待定'}\n`;
        summary += `性别: ${gender}\n`;
        summary += `血脉: ${race}\n\n`;
        summary += `出身: ${origin || '未知'}\n`;
        summary += `天赋: ${talent || '未觉醒'}\n`;
        if (customSettings) {
            summary += `自定义设定: ${customSettings}\n`;
        }
        summary += `\n--- 属性 (模式: ${appState.attributeMode === 'manual' ? `手动, ${appState.totalStatPoints}点` : '随机'}) ---\n`;
        for (const [attr, value] of Object.entries(attributes)) {
            summary += `${attr}: ${value || '?'}\n`;
        }
        DOM.finalSummary.value = summary;
    }

    function updateProfileFromDOM() {
        characterProfile.name = DOM.nameInput.value;
        characterProfile.gender = document.querySelector('input[name="gender"]:checked').value;
        characterProfile.race = DOM.raceSelect.value;
        characterProfile.origin = DOM.originInput.value;
        characterProfile.talent = DOM.talentInput.value;
        characterProfile.customSettings = DOM.customSettingsInput.value;
        syncView();
    }

    function updateManualStat(attr, value) {
        value = Math.max(MIN_STAT, Math.min(MAX_STAT, parseInt(value, 10) || MIN_STAT));
        const oldValue = characterProfile.attributes[attr];
        const diff = value - oldValue;
        if (appState.remainingStatPoints - diff < 0) { syncView(); return; }
        characterProfile.attributes[attr] = value;
        appState.remainingStatPoints -= diff;
        syncView();
    }

    // ############ 唯一的修改点 ############
    async function animateRollAndPick(dataType, targetElement, table) {
        DOM.rollingChamber.style.display = 'flex';
        appState.isAnimationSkipped = false;

        // 1. 立即确定并“锁定”结果
        const randomIndex = Math.floor(Math.random() * table.length);
        const chosenResult = table[randomIndex];
        appState.currentRollResult = chosenResult; // 将结果暂存

        const rollPromise = new Promise(resolve => {
            appState.animationPromiseResolve = resolve;

            DOM.rollResultText.textContent = `正在探寻你的${dataType}...`;
            DOM.d20Visual.textContent = '?';

            if (appState.isAnimationSkipped) { 
                resolve(chosenResult); // 如果一开始就跳过，直接用已锁定的结果
                return;
            }

            appState.activeAnimation = gsap.timeline({
                onComplete: () => {
                    DOM.rollResultText.textContent = `命运的抉择: ${chosenResult}`;
                    gsap.fromTo(DOM.d20Visual, { scale: 1.5, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: 'power2.out' });
                    setTimeout(() => resolve(chosenResult), 1500); // 动画完成时，也用锁定的结果
                }
            });
            appState.activeAnimation.to(DOM.d20Visual, { rotation: 720, scale: 1.2, duration: 1.0, ease: 'power1.in', onUpdate: () => { DOM.d20Visual.textContent = Math.floor(Math.random() * 99) + 1; } }).to(DOM.d20Visual, { scale: 1, duration: 0.2 });
        });

        // 2. 等待Promise完成，它会返回那个被“锁定”的结果
        const finalResult = await rollPromise;

        // 3. 无论如何，都使用这个最终结果
        targetElement.value = finalResult;
        DOM.rollingChamber.style.display = 'none';
        updateProfileFromDOM();
    }

    async function animateSingleRoll(attributeName) {
        return new Promise(resolve => {
            appState.animationPromiseResolve = resolve;

            const finalResult = Math.floor(Math.random() * 20) + 1;
            appState.currentRollResult = finalResult; 

            DOM.rollResultText.textContent = `正在投掷 [${attributeName}]...`;
            DOM.d20Visual.textContent = '?';

            if (appState.isAnimationSkipped) { resolve(finalResult); return; }

            appState.activeAnimation = gsap.timeline({
                onComplete: () => {
                    const revealTimeline = gsap.timeline({ onComplete: () => setTimeout(() => resolve(finalResult), 800) });
                    DOM.rollResultText.textContent = `[${attributeName}] 投掷结果: ${finalResult}`;
                    gsap.fromTo(DOM.rollResultText, { opacity: 0 }, { opacity: 1, duration: 0.5 });
                    revealTimeline.to(DOM.d20Visual, { opacity: 0, scale: 0.5, duration: 0.15, ease: 'power2.in', onComplete: () => { DOM.d20Visual.textContent = finalResult; } }).to(DOM.d20Visual, { opacity: 1, scale: 1, duration: 0.6, ease: 'back.out(1.7)' });
                }
            });
            appState.activeAnimation.to(DOM.d20Visual, { rotation: 720, scale: 1.2, duration: 1.0, ease: 'power1.in', onUpdate: () => { DOM.d20Visual.textContent = Math.floor(Math.random() * 20) + 1; } }).to(DOM.d20Visual, { scale: 1, duration: 0.2 });
        });
    }

    async function sendToSillyTavern(event) {
        const button = event.target;
        button.disabled = true;
        button.textContent = "正在构建传送法阵...";
        updateProfileFromDOM();
        const stVariables = {
            NAME: characterProfile.name || '无名者', GENDER: characterProfile.gender, RACE: characterProfile.race, ORIGIN: characterProfile.origin || '一片迷雾', TALENT: characterProfile.talent || '尚未觉醒', CUSTOM_SETTINGS: characterProfile.customSettings, DIFFICULTY: appState.difficulty, ATTRIBUTE_MODE: appState.attributeMode, ...characterProfile.attributes
        };
        const customSettingsMarkdown = stVariables.CUSTOM_SETTINGS ? `\n## **四、自定义设定**\n- ${stVariables.CUSTOM_SETTINGS}` : '';
        const slashCommand = `/send <START>\nAdmin:\n请为玩家撰写一段身临其境的开场。故事需要巧妙地融入以下角色档案中的信息，并最终引出一个需要玩家做出选择或行动的简单情境。\n\n# 角色灵魂烙印\n---\n## **一、身份**\n- **名讳:** ${stVariables.NAME}\n- **性别:** ${stVariables.GENDER}\n- **血脉:** ${stVariables.RACE}\n\n## **二、过往与天赋**\n- **出身:** ${stVariables.ORIGIN}\n- **天赋:** ${stVariables.TALENT}\n\n## **三、天命属性**\n- **力量:** ${stVariables.力量}\n- **敏捷:** ${stVariables.敏捷}\n- **体质:** ${stVariables.体质}\n- **智力:** ${stVariables.智力}\n- **感知:** ${stVariables.感知}\n- **魅力:** ${stVariables.魅力}${customSettingsMarkdown}\n---\n*（冒险难度：${stVariables.DIFFICULTY}，属性模式：${stVariables.ATTRIBUTE_MODE}）*\n|\n/trigger`;
        try {
            if (typeof insertOrAssignVariables === 'function') { await insertOrAssignVariables(stVariables); } else { console.log("SillyTavern函数 'insertOrAssignVariables' 未找到。变量数据:", stVariables); }
            if (typeof triggerSlash === 'function') { await triggerSlash(slashCommand, 'Send'); button.textContent = "传送门已开启！祝你好运！"; } else { console.log("SillyTavern函数 'triggerSlash' 未找到。"); navigator.clipboard.writeText(slashCommand).then(() => { alert('SillyTavern连接失败！开场指令已复制到你的剪贴板，请手动粘贴到聊天框发送。'); button.textContent = "指令已复制，请手动开启传送门"; }).catch(err => { alert('复制到剪贴板失败，请手动复制最终档案中的内容。'); console.error('复制失败:', err); }); }
        } catch (error) {
            console.error('与SillyTavern交互时发生错误:', error); alert('与SillyTavern交互时发生错误，详情请查看浏览器控制台。'); button.textContent = "传送失败，请重试"; button.disabled = false;
        }
    }

    DOM.difficultyOptions.forEach(btn => {
        btn.addEventListener('click', () => {
            appState.difficulty = btn.dataset.difficulty; appState.totalStatPoints = parseInt(btn.dataset.points); initializeCharacterProfile();
            gsap.to(DOM.difficultySelector, { opacity: 0, duration: 0.5, onComplete: () => { DOM.difficultySelector.style.display = 'none'; DOM.genesisFolio.style.display = 'flex'; gsap.from(DOM.genesisFolio, { opacity: 0, duration: 0.5 }); attributeNames.forEach(attr => { characterProfile.attributes[attr] = 0; }); syncView(); } });
        });
    });

    DOM.attrModeToggle.addEventListener('change', (e) => {
        appState.attributeMode = e.target.checked ? 'manual' : 'random';
        DOM.manualStatsPanel.style.display = appState.attributeMode === 'manual' ? 'block' : 'none';
        DOM.randomStatsPanel.style.display = appState.attributeMode === 'random' ? 'block' : 'none';
        if (appState.attributeMode === 'manual') initializeCharacterProfile(); else attributeNames.forEach(attr => characterProfile.attributes[attr] = 0);
        syncView();
    });

    DOM.rollStatsBtn.addEventListener('click', async () => {
        DOM.rollStatsBtn.disabled = true;
        DOM.rollingChamber.style.display = 'flex';
        appState.isAnimationSkipped = false;
        for (const attr of attributeNames) {
            if (appState.isAnimationSkipped) {
                characterProfile.attributes[attr] = Math.floor(Math.random() * 20) + 1;
                syncView();
                continue;
            }
            const result = await animateSingleRoll(attr);
            characterProfile.attributes[attr] = result;
            syncView();
        }
        DOM.rollingChamber.style.display = 'none';
        DOM.rollStatsBtn.disabled = false;
        updateProfileFromDOM(); 
    });

    DOM.rollOriginBtn.addEventListener('click', () => animateRollAndPick('出身', DOM.originInput, randomOriginTable));
    DOM.rollTalentBtn.addEventListener('click', () => animateRollAndPick('天赋', DOM.talentInput, randomTalentTable));

    [...DOM.genderRadios, DOM.nameInput, DOM.raceSelect, DOM.originInput, DOM.talentInput, DOM.customSettingsInput].forEach(el => {
        const eventType = el.type === 'radio' ? 'change' : 'input';
        el.addEventListener(eventType, updateProfileFromDOM);
    });

    DOM.skipRollBtn.addEventListener('click', () => {
        if (appState.isAnimationSkipped) return;
        appState.isAnimationSkipped = true;
        if (appState.activeAnimation) appState.activeAnimation.kill();
        if (appState.animationPromiseResolve) {
            appState.animationPromiseResolve(appState.currentRollResult);
            appState.animationPromiseResolve = null;
        }
    });

    function initialize() {
        for (const raceName of Object.keys(ancestryData)) DOM.raceSelect.add(new Option(raceName, raceName));
        DOM.manualAttributesGrid.innerHTML = '';
        DOM.randomAttributesGrid.innerHTML = '';
        attributeNames.forEach(attr => {
            const manualItem = document.createElement('div');
            manualItem.className = 'attribute-item';
            manualItem.innerHTML = `<span class="attr-name">${attr}</span><div class="manual-attr-controls"><button id="manual-attr-minus-${attr}">-</button><input type="number" id="manual-attr-input-${attr}" min="${MIN_STAT}" max="${MAX_STAT}"><button id="manual-attr-plus-${attr}">+</button></div>`;
            DOM.manualAttributesGrid.appendChild(manualItem);
            const randomItem = document.createElement('div');
            randomItem.className = 'attribute-item';
            randomItem.innerHTML = `<span class="attr-name">${attr}</span><span class="random-attr-value" id="random-attr-val-${attr}">0</span>`;
            DOM.randomAttributesGrid.appendChild(randomItem);
        });
        attributeNames.forEach(attr => {
            document.getElementById(`manual-attr-plus-${attr}`).addEventListener('click', () => updateManualStat(attr, characterProfile.attributes[attr] + 1));
            document.getElementById(`manual-attr-minus-${attr}`).addEventListener('click', () => updateManualStat(attr, characterProfile.attributes[attr] - 1));
            document.getElementById(`manual-attr-input-${attr}`).addEventListener('input', (e) => updateManualStat(attr, e.target.value));
        });
        DOM.randomStatsPanel.style.display = 'block';
        DOM.finalizeBtn.addEventListener('click', sendToSillyTavern);
    }

    initialize();
});
</script>

</body>
</html>
