    <div class="page-wrapper">
        <article class="content-prose">
$1
        </article>
    </div>
    <button id="theme-toggle" class="theme-switch-button" aria-label="切换阅读模式">
        <span id="theme-icon">🌙</span>
    </button>
    <script>
    'use strict';

    // ---- 元素选择 ----
    const themeToggleButton = document.getElementById('theme-toggle');
    const themeIcon = document.getElementById('theme-icon');
    const bodyElement = document.body;
    const articleElement = document.querySelector('article.content-prose');

    // ---- 常量定义 ----
    const THEME_LIGHT = 'light';
    const THEME_DARK = 'dark';
    const STORAGE_KEY = 'reader_theme_preference';

    // ---- 功能函数 ----
    function applyTheme(theme) {
        if (theme === THEME_DARK) {
            bodyElement.classList.add('eye-care-theme');
            themeIcon.textContent = '☀️';
        } else {
            bodyElement.classList.remove('eye-care-theme');
            themeIcon.textContent = '🌙';
        }
    }

    function toggleTheme() {
        const isDark = bodyElement.classList.contains('eye-care-theme');
        const newTheme = isDark ? THEME_LIGHT : THEME_DARK;
        applyTheme(newTheme);
        try {
            localStorage.setItem(STORAGE_KEY, newTheme);
        } catch (error) {
            console.error("无法访问本地存储，主题偏好无法保存。", error);
        }
    }

    function highlightQuotes() {
        if (!articleElement) {
            console.warn('未找到 <article> 元素，无法高亮引言。');
            return;
        }
        if(articleElement.innerHTML.includes('class="dialogue-quote"')) return;

        const quoteRegex = /(["“])(.+?)(["”])/g;
        const replacement = '<span class="dialogue-quote">$&</span>';
        articleElement.innerHTML = articleElement.innerHTML.replace(quoteRegex, replacement);
    }

    // ---- 事件监听与初始化 ----
    themeToggleButton.addEventListener('click', toggleTheme);

    document.addEventListener('DOMContentLoaded', () => {
        let savedTheme;
        try {
            savedTheme = localStorage.getItem(STORAGE_KEY) || THEME_LIGHT;
        } catch (error) {
            console.error("无法访问本地存储，将使用默认主题。", error);
            savedTheme = THEME_LIGHT;
        }
        applyTheme(savedTheme);
        highlightQuotes();
    });

    </script>
</body>
</html>
