        }

        .page-wrapper {
            color: var(--text-color);
            min-height: 100vh;
            background:
                radial-gradient(circle at 15% 20%, var(--bg-sun-spot), transparent 40%),
                radial-gradient(circle at 45% 50%, var(--bg-sun-spot), transparent 50%),
                radial-gradient(circle at 80% 75%, var(--bg-sun-spot), transparent 45%),
                radial-gradient(circle at 75% 90%, var(--bg-sun-spot), transparent 35%);
            background-size: 100% 100%;
            background-attachment: fixed;
            padding: 0 0.5rem;
        }

        .content-prose {
            /* 
              【核心修改】
              重新引入卡片概念，并增加金色镶边和圆角。
            */
            max-width: 800px;
            margin: 0 auto;
            padding: 1.5rem 2rem 3rem 2rem;
            font-size: 1.1rem;
            line-height: 1.8;
            white-space: pre-wrap;
            text-align: justify;

            /* 1. 圆角 */
            border-radius: 12px;

            /* 2. 创建一个透明边框为“镶边”留出空间 */
            border: 3px solid transparent;

            /* 3. 使用双重背景和 background-clip 创建渐变边框 */
            background-image: 
                linear-gradient(var(--card-bg-color), var(--card-bg-color)), /* 上层：卡片背景 */
                linear-gradient(145deg, #f9e28d, #c9a044); /* 下层：金色渐变 */
            background-origin: border-box;
            background-clip: padding-box, border-box; /* 上层裁切到内边距，下层填满边框 */

            /* 4. 恢复卡片的模糊和阴影效果，增强立体感 */
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            box-shadow: 0 4px 25px rgba(0,0,0,0.1);

            transition: color 0.5s ease, background-color 0.5s ease, box-shadow 0.5s ease;
        }

        /* --- 正文高亮样式 --- */
        .content-prose em {
            color: var(--emphasis-color); font-style: italic; transition: color 0.5s ease;
        }
        .content-prose .dialogue-quote {
            color: var(--quote-color); font-weight: 500; transition: color 0.5s ease;
        }

        .theme-switch-button {
            position: fixed; top: 20px; right: 20px;
            width: 48px; height: 48px;
            border-radius: 50%;
            border: 2px solid var(--button-border-color);
            background-color: var(--button-bg-color);
            color: var(--text-color);
            font-size: 1.4rem;
            cursor: pointer; z-index: 1000;
            display: flex; justify-content: center; align-items: center;
            backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px);
            transition: all 0.3s ease;
        }
        .theme-switch-button:hover { transform: scale(1.1); }

        /* --- 护眼模式样式 --- */
        .eye-care-theme body {
            background-color: var(--bg-color-dark);
        }
        .eye-care-theme .page-wrapper {
            color: var(--text-color-dark);
            background: var(--bg-color-dark);
        }
        /* 在护眼模式下，移除卡片和镶边效果，回归纯粹阅读 */
        .eye-care-theme .content-prose {
            border-color: transparent;
            background-image: none;
            background-color: transparent;
            backdrop-filter: none;
            -webkit-backdrop-filter: none;
            box-shadow: none;
        }
        .eye-care-theme .theme-switch-button {
            border-color: var(--button-border-color-dark);
            background-color: var(--button-bg-color-dark);
            color: var(--text-color-dark);
        }
        .eye-care-theme .content-prose em { color: var(--emphasis-color-dark); }
        .eye-care-theme .content-prose .dialogue-quote { color: var(--quote-color-dark); }

        /* --- 响应式设计 --- */
        @media (max-width: 768px) {
            .page-wrapper { padding: 0; }
            .content-prose { 
                padding: 1.5rem 1rem 2.5rem 1rem; 
                font-size: 1rem;
                min-height: 100vh;
                /* 在移动端，移除圆角和边框，使其占满全屏 */
                border-radius: 0;
                border-width: 0;
            }
            .theme-switch-button { 
                width: 42px; height: 42px; font-size: 1.2rem; top: 15px; right: 15px;
            }
        }
    </style>
</head>
<body class="">
    <div class="page-wrapper">
        <article class="content-prose">
$1
        </article>
    </div>
    <button id="theme-toggle" class="theme-switch-button" aria-label="切换阅读模式">
        <span id="theme-icon">🌙</span>
    </button>
    <script>
    'use strict';

    // ---- 元素选择 ----
    const themeToggleButton = document.getElementById('theme-toggle');
    const themeIcon = document.getElementById('theme-icon');
    const bodyElement = document.body;
    const articleElement = document.querySelector('article.content-prose');

    // ---- 常量定义 ----
    const THEME_LIGHT = 'light';
    const THEME_DARK = 'dark';
    const STORAGE_KEY = 'reader_theme_preference';

    // ---- 功能函数 ----
    function applyTheme(theme) {
        if (theme === THEME_DARK) {
            bodyElement.classList.add('eye-care-theme');
            themeIcon.textContent = '☀️';
        } else {
            bodyElement.classList.remove('eye-care-theme');
            themeIcon.textContent = '🌙';
        }
    }

    function toggleTheme() {
        const isDark = bodyElement.classList.contains('eye-care-theme');
        const newTheme = isDark ? THEME_LIGHT : THEME_DARK;
        applyTheme(newTheme);
        try {
            localStorage.setItem(STORAGE_KEY, newTheme);
        } catch (error) {
            console.error("无法访问本地存储，主题偏好无法保存。", error);
        }
    }

    function highlightQuotes() {
        if (!articleElement) {
            console.warn('未找到 <article> 元素，无法高亮引言。');
            return;
        }
        if(articleElement.innerHTML.includes('class="dialogue-quote"')) return;

        const quoteRegex = /(["“])(.+?)(["”])/g;
        const replacement = '<span class="dialogue-quote">$&</span>';
        articleElement.innerHTML = articleElement.innerHTML.replace(quoteRegex, replacement);
    }

    // ---- 事件监听与初始化 ----
    themeToggleButton.addEventListener('click', toggleTheme);

    document.addEventListener('DOMContentLoaded', () => {
        let savedTheme;
        try {
            savedTheme = localStorage.getItem(STORAGE_KEY) || THEME_LIGHT;
        } catch (error) {
            console.error("无法访问本地存储，将使用默认主题。", error);
            savedTheme = THEME_LIGHT;
        }
        applyTheme(savedTheme);
        highlightQuotes();
    });

    </script>
</body>
</html>
